#define main prior_graph_main
#include "graph-check.cpp"
#undef main
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();for(int cycle=0;cycle<3;cycle++){std::string label="Core lifecycle "+std::to_string(cycle+1)+": ";check(obs_startup("en-US",nullptr,nullptr),label+"real startup");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=OBS_SOURCE_AUDIO;i.get_name=name;i.create=create;i.destroy=destroy;i.enum_active_sources=enumerate;i.enum_all_sources=enumerate;obs_register_source(&i);auto *p=source("cycle parent"),*c=source("cycle child");obs_source_inc_active(p);check(obs_source_add_active_child(p,c)&&obs_source_add_active_child(p,c),label+"duplicate active attachment");count(c,2,2,label+"two inherited MAIN credits");obs_source_dec_active(p);obs_source_remove_active_child(p,c);obs_source_release(c);obs_source_release(p);studio_graph_drain();check(destroyed==(cycle+1)*2,label+"fallback final edge drained and both sources destroyed");obs_shutdown();check(!obs_initialized(),label+"real shutdown complete");}auto *d=obs_data_create();obs_data_set_array(d,"checks",checks);obs_data_set_int(d,"failures",failures);obs_data_set_bool(d,"passed",!failures);obs_data_save_json_safe(d,argv[1],"tmp",nullptr);obs_data_release(d);obs_data_array_release(checks);return failures?1:0;}
